const getMergedLandingRequestForChange = `-- name: GetMergedLandingRequestForChange :one
SELECT
    lr.id, lr.repository_id, lr.number, lr.request_id, lr.create_request_hash, lr.title, lr.body, lr.state, lr.author_id, lr.target_bookmark, lr.source_bookmark, lr.conflict_status, lr.stack_size, lr.agent_authored, lr.author_agent_session_id, lr.turn_party, lr.turn_actor_id, lr.turn_since, lr.turn_reason, lr.turn_revision_id, lr.landed_revisions, lr.auto_land_enabled, lr.auto_land_set_by, lr.auto_land_set_at, lr.auto_land_checked_at, lr.queued_by, lr.queued_at, lr.landing_started_at, lr.closed_at, lr.merged_at, lr.created_at, lr.updated_at,
    COALESCE(
      lr.landed_revisions -> lrc.change_id ->> 'commit_id',
      (
        SELECT cr.commit_id
        FROM change_revisions AS cr
        WHERE cr.repository_id = lr.repository_id
          AND cr.change_id = lrc.change_id
          AND cr.created_at <= lr.merged_at
        ORDER BY cr.seq DESC
        LIMIT 1
      ),
      c.commit_id,
      ''
    )::text AS landed_revision
FROM landing_requests AS lr
JOIN landing_request_changes AS lrc ON lrc.landing_request_id = lr.id
LEFT JOIN changes AS c
  ON c.repository_id = lr.repository_id
 AND c.change_id = lrc.change_id
WHERE lr.repository_id = $1
  AND lrc.change_id = $2
  AND lr.state = 'merged'
ORDER BY lr.merged_at DESC, lr.id DESC
LIMIT 1
`

